#### 860\. 柠檬水找零（random）
(https://leetcode.cn/problems/lemonade-change/)
```cpp
class Solution {
public:
    bool lemonadeChange(vector<int>& bills) {
        int five = 0, ten = 0, twenty = 0;
        for (int& bill : bills) {
            if (bill == 5) five++;
            if (bill == 10) {
                if (five == 0)return false;
                else five--;
                ten++;
            }
            if (bill == 20) {
                if (ten != 0 && five != 0) {
                    ten--, five--, twenty++;
                    continue;
                }
                if (five >= 3) {
                    five -= 3;
                    twenty++;
                    continue;
                }
                else return false;
            }
        }
        return true;
    }
};
```
-   If-else 模拟题我居然还想优先队列

